/**
 * Node SDK conformance tests.
 *
 * Most of these replay `sdk/testdata/vectors.json`, generated by the Python implementation. That
 * is the point: three SDKs verifying the same credentials is only useful if they agree, and
 * agreement asserted in a README is not agreement. If this suite passes, a credential the Python
 * verifier accepts is accepted here, and — more importantly — a credential Python rejects is
 * rejected here, with the same error code.
 *
 *     node --test sdk/node/test/
 */

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { after, describe, it } from 'node:test';
import { fileURLToPath } from 'node:url';

import {
  AgentVerifier,
  BloomFilter,
  KeySet,
  MalformedToken,
  NonceCache,
  RegistryUnavailable,
  TrustStore,
  buildTrustStore,
  parseSignatureInput,
} from '../index.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
// AIDR_VECTORS: replay another signer's vectors (the conformance gate, docs/13).
const VECTORS = JSON.parse(
  readFileSync(process.env.AIDR_VECTORS || resolve(HERE, '../../testdata/vectors.json'), 'utf8'),
);

// The vectors contain real, time-bound artefacts: RFC 9421 signatures expire after 300 s and
// credentials after 15 minutes. Evaluating at the pinned instant is what keeps this suite
// meaningful a week after the vectors were generated, rather than for five minutes.
const NOW = new Date(VECTORS.evaluate_at * 1000);

function verifierFor(suite, { expectedAudience = null, ...policy } = {}) {
  const trust = buildTrustStore(suite.jwks, {
    deltaToken: suite.revocation.delta_before_revocation,
    expectedIssuer: suite.issuer,
  });
  return new AgentVerifier(trust, {
    policy: { expectedIssuer: suite.issuer, expectedAudience, ...policy },
    nonceSeen: new NonceCache(),
  });
}

for (const suite of VECTORS.suites) {
  describe(`cross-language conformance — ${suite.algorithm}`, () => {
    it('bootstraps a trust store from the published JWKS and delta', () => {
      const trust = buildTrustStore(suite.jwks, {
        deltaToken: suite.revocation.delta_before_revocation,
        expectedIssuer: suite.issuer,
      });
      const health = trust.health();
      assert.equal(health.keys, 1);
      // A delta from serial 0 is a full snapshot, so local answers are definitive.
      assert.equal(health.revocationExact, true);
      // The age every verifier judges from is the delta's own signed iat.
      const signedAt = JSON.parse(Buffer.from(suite.revocation.delta_before_revocation.split('.')[1], 'base64url')).iat;
      assert.equal(health.revocationIssuedAt, signedAt);
      assert.ok(signedAt <= VECTORS.evaluate_at);
    });

    // freshness_cases: trust loaded at NOW, each verified at its own, later instant.
    for (const testCase of [...suite.cases, ...suite.freshness_cases]) {
      it(testCase.name, () => {
        const verifier = verifierFor(suite, {
          expectedAudience: testCase.expected_audience ?? null,
          minAssurance: testCase.min_assurance ?? 0,
        });
        const { result, error } = verifier.tryVerify({
          method: testCase.method,
          url: testCase.url,
          headers: testCase.headers,
          now: testCase.evaluate_at ? new Date(testCase.evaluate_at * 1000) : NOW,
        });

        if (testCase.expect === 'allow') {
          assert.equal(error, null, `expected allow, got ${error?.code}: ${error?.message}`);
          assert.equal(result.aid, suite.aid);
          assert.equal(result.organization, suite.organization);
          assert.equal(result.assurance, suite.expected_assurance);
          assert.deepEqual([result.agal, result.oal, result.kal],
            [suite.expected_agal, suite.expected_oal, suite.expected_kal]);
          assert.deepEqual(result.capabilities, suite.expected_capabilities);
        } else {
          assert.notEqual(error, null, 'expected a denial, got an acceptance');
          if (testCase.expect_code) {
            assert.equal(error.code, testCase.expect_code,
              `expected ${testCase.expect_code}, got ${error.code}: ${error.message}`);
          }
        }
      });
    }

    // Multi-step cases against one verifier and one replay cache, in order.
    for (const sequence of suite.sequences) {
      it(`sequence: ${sequence.name}`, () => {
        const verifier = verifierFor(suite);
        for (const step of sequence.steps) {
          const testCase = suite.cases.find((c) => c.name === step.case);
          const { error } = verifier.tryVerify({
            method: testCase.method, url: testCase.url, headers: testCase.headers, now: NOW,
          });
          if (step.expect === 'allow') {
            assert.equal(error, null, `${step.case}: expected allow, got ${error?.code}`);
          } else {
            assert.notEqual(error, null, `${step.case}: expected a denial`);
            if (step.expect_code) assert.equal(error.code, step.expect_code);
          }
        }
      });
    }

    it('separates what we verified from what the owner declared', () => {
      const verifier = verifierFor(suite);
      const allowCase = suite.cases.find((c) => c.expect === 'allow' && !c.expected_audience);
      const { result } = verifier.tryVerify({
        method: allowCase.method, url: allowCase.url, headers: allowCase.headers, now: NOW,
      });
      // The model family is self-asserted and must never sit alongside verified claims.
      assert.equal(result.declared.model_family, 'custom-llm');
      assert.equal(result.model_family, undefined);
    });

    it('refuses a revoked agent once the delta is refreshed', () => {
      const trust = buildTrustStore(suite.jwks, {
        deltaToken: suite.revocation.delta_after_revocation,
        expectedIssuer: suite.issuer,
      });
      const verifier = new AgentVerifier(trust, {
        policy: { expectedIssuer: suite.issuer }, nonceSeen: new NonceCache(),
      });
      const allowCase = suite.cases.find((c) => c.expect === 'allow' && !c.expected_audience);

      const { error } = verifier.tryVerify({
        method: allowCase.method, url: allowCase.url, headers: allowCase.headers, now: NOW,
      });
      assert.equal(error?.code, 'aidr.verify.agent_revoked');
    });

    it('finds the revoked identifier in the published bloom filter', () => {
      const trust = TrustStore.fromJwks(suite.jwks, { expectedIssuer: suite.issuer });
      trust.ingestFilter(suite.revocation.filter_after_revocation);
      // The filter must agree with the delta: this is the cross-SDK hash construction check.
      assert.equal(trust.revocation.filter.has(suite.aid), true);
      // An identifier the generator confirmed this filter rules out (a bloom filter has false positives).
      const absent = suite.revocation.filter_absent_probe ?? 'aid:v1:acme-corp:NEVER-ISSUED:0000';
      assert.equal(trust.revocation.filter.has(absent), false);
    });

    it('enforces the site assurance floor', () => {
      const verifier = verifierFor(suite, { minAssurance: 3 });
      const allowCase = suite.cases.find((c) => c.expect === 'allow' && !c.expected_audience);
      const { error } = verifier.tryVerify({
        method: allowCase.method, url: allowCase.url, headers: allowCase.headers, now: NOW,
      });
      assert.equal(error?.code, 'aidr.verify.assurance_too_low');
    });

    it('enforces required capabilities', () => {
      const verifier = verifierFor(suite, { requiredCapabilities: ['payment.initiate'] });
      const allowCase = suite.cases.find((c) => c.expect === 'allow' && !c.expected_audience);
      const { error } = verifier.tryVerify({
        method: allowCase.method, url: allowCase.url, headers: allowCase.headers, now: NOW,
      });
      assert.equal(error?.code, 'aidr.verify.capability_denied');
    });

    it('refuses a replayed request', () => {
      const verifier = verifierFor(suite);
      const allowCase = suite.cases.find((c) => c.expect === 'allow' && !c.expected_audience);
      const request = {
        method: allowCase.method, url: allowCase.url, headers: allowCase.headers, now: NOW,
      };

      assert.equal(verifier.tryVerify(request).error, null);
      assert.equal(verifier.tryVerify(request).error?.code, 'aidr.verify.replay_detected');
    });
  });
}

describe('fail-closed revocation', () => {
  const suite = VECTORS.suites[0];
  const allowCase = suite.cases.find((c) => c.expect === 'allow' && !c.expected_audience);

  it('an unbootstrapped store denies by default', () => {
    // A site that never loaded revocation state is not verifying; it must not pretend to.
    const trust = new TrustStore(KeySet.fromJwks(suite.jwks), { expectedIssuer: suite.issuer });
    const verifier = new AgentVerifier(trust, {
      policy: { expectedIssuer: suite.issuer }, nonceSeen: new NonceCache(),
    });
    const { error } = verifier.tryVerify({
      method: allowCase.method, url: allowCase.url, headers: allowCase.headers, now: NOW,
    });
    assert.ok(error instanceof RegistryUnavailable);
  });

  it('soft-fail is available but must be chosen', () => {
    const trust = new TrustStore(KeySet.fromJwks(suite.jwks), { expectedIssuer: suite.issuer });
    const verifier = new AgentVerifier(trust, {
      policy: { expectedIssuer: suite.issuer, allowUnknownRevocation: true },
      nonceSeen: new NonceCache(),
    });
    const { result, error } = verifier.tryVerify({
      method: allowCase.method, url: allowCase.url, headers: allowCase.headers, now: NOW,
    });
    assert.equal(error, null);
    assert.ok(result.warnings.some((w) => w.includes('revocation status unverified')));
  });

  it('a bloom hit falls through to the online check', () => {
    const trust = TrustStore.fromJwks(suite.jwks, { expectedIssuer: suite.issuer });
    trust.ingestFilter(suite.revocation.filter_after_revocation);

    const checked = [];
    const verifier = new AgentVerifier(trust, {
      policy: {
        expectedIssuer: suite.issuer,
        onlineRevocationCheck: (aid) => { checked.push(aid); return false; },
      },
      nonceSeen: new NonceCache(),
    });
    const { error } = verifier.tryVerify({
      method: allowCase.method, url: allowCase.url, headers: allowCase.headers, now: NOW,
    });
    assert.equal(error, null);
    assert.deepEqual(checked, [suite.aid]);
  });
});

describe('rejecting unsafe input', () => {
  const suite = VECTORS.suites[0];

  it('refuses a JWKS containing private key material', () => {
    assert.throws(
      () => KeySet.fromJwks({ keys: [{ ...suite.jwks.keys[0], d: 'AAAA' }] }),
      (error) => error instanceof MalformedToken,
    );
  });

  it('refuses a delta that would leave a gap', () => {
    // Applying a delta that begins past the local serial would silently lose every revocation in
    // between. A fresh store is at serial 0; this delta starts at 50.
    const trust = TrustStore.fromJwks(suite.jwks, { expectedIssuer: suite.issuer });
    assert.throws(() => trust.ingestDelta(suite.revocation.delta_with_gap),
      (error) => error.code === 'aidr.registry.unavailable');
  });

  it('refuses a delta from an unexpected issuer', () => {
    const trust = TrustStore.fromJwks(suite.jwks, { expectedIssuer: 'https://impostor.example' });
    assert.throws(() => trust.ingestDelta(suite.revocation.delta_before_revocation),
      (error) => error.code === 'aidr.verify.unknown_issuer');
  });

  for (const raw of ['', 'garbage', 'sig1="not-a-list"', 'sig1=(unclosed']) {
    it(`refuses malformed Signature-Input: ${JSON.stringify(raw)}`, () => {
      assert.throws(() => parseSignatureInput(raw), (error) => error instanceof MalformedToken);
    });
  }
});

describe('bloom filter construction matches the other SDKs', () => {
  it('decodes a published filter and finds the revoked identifier', () => {
    // The hash construction (SHA-256, two 64-bit halves, enhanced double hashing) must match the
    // Python implementation exactly, or a revoked agent silently verifies in one language.
    for (const suite of VECTORS.suites) {
      const trust = TrustStore.fromJwks(suite.jwks, { expectedIssuer: suite.issuer });
      trust.ingestFilter(suite.revocation.filter_after_revocation);
      assert.equal(trust.revocation.filter.has(suite.aid), true, suite.algorithm);
    }
  });

  it('rejects a filter whose declared size does not match its bits', () => {
    assert.throws(() => BloomFilter.fromJSON({ format: 1, m: 1024, k: 7, bits: 'AAAA' }));
  });
});

describe('nonce cache', () => {
  it('reports a repeated nonce', () => {
    const cache = new NonceCache();
    assert.equal(cache.check('abc'), false);
    assert.equal(cache.check('abc'), true);
  });

  it('refuses when full of live nonces rather than forgetting one', () => {
    const cache = new NonceCache({ ttlSeconds: 600, maxEntries: 100 });
    for (let i = 0; i < 100; i += 1) cache.check(`nonce-${i}`);
    assert.throws(() => cache.check('one-too-many'), RegistryUnavailable);
    assert.equal(cache.check('nonce-0'), true);
    assert.equal(cache.size, 100);
  });

  it('makes room from expired entries', () => {
    const cache = new NonceCache({ ttlSeconds: 0, maxEntries: 2 });
    for (let i = 0; i < 10; i += 1) assert.equal(cache.check(`nonce-${i}`), false);
    assert.ok(cache.size <= 2);
  });

  it('remembers nonces for twice the signature age by default', () => {
    assert.equal(new NonceCache().ttl, 600_000);
  });
});

after(() => {
  const total = VECTORS.suites.reduce((sum, suite) => sum + suite.cases.length, 0);
  console.log(`\nreplayed ${total} cross-language vectors from the Python implementation`);
});
